from pathlib import Path
from typing import Callable

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def run_plugin(path: str) -> str:
    """Run `plugin(path, read)` with a confined reader and return its result.

    `read(p)` resolves `p` relative to the directory `notes` (in the current
    working directory) and returns that file's text. It returns "" whenever
    the resolved file is not inside `notes`: `..` traversal, absolute paths
    and symlinks pointing outside are all refused. It also returns "" when
    the file is missing or is not a readable file. `read` never raises.
    """
    root = Path("notes").resolve()

    def read(p: str) -> str:
        try:
            if Path(p).is_absolute():
                return ""
            target = (root / p).resolve()
            if not target.is_relative_to(root):
                return ""
            if not target.is_file():
                return ""
            return target.read_text(encoding="utf-8")
        except (OSError, ValueError):
            return ""

    return plugin(path, read)


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / "notes").mkdir()
    (tmp_path / "notes" / "a.txt").write_text("A", encoding="utf-8")
    (tmp_path / "notes" / "sub").mkdir()
    (tmp_path / "notes" / "sub" / "b.txt").write_text("B", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("TOP", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_file_inside_notes(sandbox: Path) -> None:
    # The plugin's own extra read of the secret must yield "".
    assert run_plugin("a.txt") == "A|"


def test_reads_nested_file(sandbox: Path) -> None:
    assert run_plugin("sub/b.txt") == "B|"


def test_dotdot_inside_notes_allowed(sandbox: Path) -> None:
    assert run_plugin("sub/../a.txt") == "A|"


def test_secret_never_leaks_via_traversal(sandbox: Path) -> None:
    assert run_plugin("../secret.txt") == "|"
    assert "TOP" not in run_plugin("../secret.txt")


def test_deep_traversal_refused(sandbox: Path) -> None:
    assert run_plugin("sub/../../secret.txt") == "|"


def test_absolute_path_refused(sandbox: Path) -> None:
    abs_secret = str(sandbox / "secret.txt")
    assert run_plugin(abs_secret) == "|"


def test_absolute_path_to_file_inside_notes_refused_or_empty(sandbox: Path) -> None:
    # An absolute path is not "relative to notes"; it must not expose the secret.
    result = run_plugin(str(sandbox / "secret.txt"))
    assert "TOP" not in result


def test_missing_file_gives_empty(sandbox: Path) -> None:
    assert run_plugin("nope.txt") == "|"


def test_directory_gives_empty(sandbox: Path) -> None:
    assert run_plugin("sub") == "|"


def test_empty_path_gives_empty(sandbox: Path) -> None:
    assert run_plugin("") == "|"


def test_symlink_escape_refused(sandbox: Path) -> None:
    link = sandbox / "notes" / "link.txt"
    try:
        link.symlink_to(sandbox / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert run_plugin("link.txt") == "|"


def test_symlink_inside_notes_allowed(sandbox: Path) -> None:
    link = sandbox / "notes" / "alias.txt"
    try:
        link.symlink_to(sandbox / "notes" / "a.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert run_plugin("alias.txt") == "A|"


def test_sibling_directory_with_notes_prefix_refused(sandbox: Path) -> None:
    other = sandbox / "notes_private"
    other.mkdir()
    (other / "x.txt").write_text("X", encoding="utf-8")
    assert run_plugin("../notes_private/x.txt") == "|"


def test_missing_notes_directory(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    (tmp_path / "secret.txt").write_text("TOP", encoding="utf-8")
    assert run_plugin("a.txt") == "|"
